    assert_eq!(candidate(vec!["cat","bat","rat","hat"], vec![1,2,3,4]), vec!['cat', 'bat', 'rat', 'hat']);
    assert_eq!(candidate(vec!["abc","bcd","cde"], vec![1,1,1]), vec!['abc']);
    assert_eq!(candidate(vec!["cat","bat","rat","hat"], vec![1,1,1,2]), vec!['cat', 'hat']);
    assert_eq!(candidate(vec!["word","wird","wordy"], vec![1,2,3]), vec!['word', 'wird']);
}
